return {["scripts/actions/weaponskills/shining_blade.lua"]={["Path"]="scripts/actions/weaponskills/shining_blade.lua",["SHA256"]="ffc6d762fb459bb4c9e53b479ba0ad7016bff651259424453985f8c8eaf295a4",["Text"]="-----------------------------------\n-- Shining Blade\n-- Sword weapon skill\n-- Skill Level: 100\n-- Deals light elemental damage to enemy. Damage varies with TP.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: Light\n-- Modifiers: STR:40%  MND:40%\n-- 100%TP    200%TP    300%TP\n-- 1.125      2.222      3.523\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 2.0, 2.5 }\n    params.str_wsc = 0.2 params.mnd_wsc = 0.2\n    params.ele = xi.element.LIGHT\n    params.skill = xi.skill.SWORD\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.125, 2.222, 3.523 }\n        params.str_wsc = 0.4 params.mnd_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shining_strike.lua"]={["Path"]="scripts/actions/weaponskills/shining_strike.lua",["SHA256"]="025f3ea075109b4976c06408058630568a04fff46927d592b9bc0277cf6697f3",["Text"]="-----------------------------------\n-- Shining Strike\n-- Club weapon skill\n-- Skill level: 5\n-- Deals light elemental damage to enemy. Damage varies with TP.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:40%  MND:40%\n-- 100%TP    200%TP    300%TP\n-- 1.625       3       4.625\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 1.75, 2.5 }\n    params.str_wsc = 0.2 params.mnd_wsc = 0.2\n    params.ele = xi.element.LIGHT\n    params.skill = xi.skill.CLUB\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.625, 3.0, 4.625 }\n        params.str_wsc = 0.4 params.mnd_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shockwave.lua"]={["Path"]="scripts/actions/weaponskills/shockwave.lua",["SHA256"]="e0cfbb8bbc94e867d700be05071b82d9a934ced68c2dbd7a9700e49aee00a605",["Text"]="-----------------------------------\n-- Shockwave\n-- Great Sword weapon skill\n-- Skill level: 150\n-- Delivers an area of effect attack. Sleeps enemies. Duration of effect varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Aqua Gorget.\n-- Aligned with the Aqua Belt.\n-- Element: None\n-- Modifiers: STR:30%  MND:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params  = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.SLEEP_I\n    local actionElement = xi.element.DARK\n    local power         = 1\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shoulder_tackle.lua"]={["Path"]="scripts/actions/weaponskills/shoulder_tackle.lua",["SHA256"]="9dddfb8682d7aedc564544dce56794fbbbe592fb05bec4cfceaed7ed9b64cc9d",["Text"]="-----------------------------------\n-- Shoulder Tackle\n-- Hand-to-Hand weapon skill\n-- Skill Level: 40\n-- Stuns target. Chance of stunning varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Aqua Gorget & Thunder Gorget.\n-- Aligned with the Aqua Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: VIT:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1, 1, 1 }\n    params.vit_wsc = 0.3\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/2417.html\n        params.vit_wsc     = 1\n    end\n\n    -- Handle status effect\n    local effectId      = xi.effect.STUN\n    local actionElement = xi.element.THUNDER\n    local power         = 1\n    local duration      = math.floor(tp / 500 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/sickle_moon.lua"]={["Path"]="scripts/actions/weaponskills/sickle_moon.lua",["SHA256"]="b41fd396abb19149eaae3707bac6410a786d75b0810759475f37bc55e6195748",["Text"]="-----------------------------------\n-- Sickle Moon\n-- Great Sword weapon skill\n-- Skill level: 200\n-- Delivers a two-hit attack. Damage varies with TP.\n-- Modifiers: STR:40%  AGI:40%\n-- 100%TP     200%TP     300%TP\n-- 1.5         2        2.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.5, 2.0, 2.75 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.2 params.agi_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.agi_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/sidewinder.lua"]={["Path"]="scripts/actions/weaponskills/sidewinder.lua",["SHA256"]="f1ce08793e0b2f0e3c664684cfeac43db7ea36eede3d7544048f4405c9ca509e",["Text"]="-----------------------------------\n-- Sidewinder\n-- Archery weapon skill\n-- Skill level: 175\n-- Delivers an inparams.accurate attack that deals quintuple damage. params.accuracy varies with TP.\n-- Aligned with the Aqua Gorget, Light Gorget & Breeze Gorget.\n-- Aligned with the Aqua Belt, Light Belt & Breeze Belt.\n-- Element: None\n-- Modifiers: STR:20%  AGI:50%\n-- 100%TP    200%TP    300%TP\n-- 5.00      5.00      5.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 5.0, 5.0, 5.0 }\n    params.str_wsc = 0.16 params.agi_wsc = 0.25\n    params.accVaries = { -50, 0, 0 } -- TODO: verify 3k\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.2 params.agi_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/skewer.lua"]={["Path"]="scripts/actions/weaponskills/skewer.lua",["SHA256"]="5e8ca41f83c3ad11446a76e1dba38f24c5903bc93938d3ef3d81571877c5cdd1",["Text"]="-----------------------------------\n-- Skewer\n-- Polearm weapon skill\n-- Skill Level: 200\n-- Delivers a three-hit attack. Chance of params.critical hit varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Light Gorget & Thunder Gorget.\n-- Aligned with the Light Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.35\n    params.critVaries = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/skullbreaker.lua"]={["Path"]="scripts/actions/weaponskills/skullbreaker.lua",["SHA256"]="c4dabaf47ae42c149b869745e90536fc8315fbecbbd840e3b40ff1e1b7b39b4a",["Text"]="-----------------------------------\n-- Skullbreaker\n-- Club weapon skill\n-- Skill level: 150\n-- Lowers enemy's INT. Chance of lowering INT varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Snow Gorget & Aqua Gorget.\n-- Aligned with the Snow Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR:100%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.3\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1\n    end\n\n    -- Handle status effect\n    local effectId      = xi.effect.INT_DOWN\n    local actionElement = xi.element.FIRE\n    local power         = 10\n    local duration      = math.floor(140 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/slice.lua"]={["Path"]="scripts/actions/weaponskills/slice.lua",["SHA256"]="4e65ea13803677c2666acfad03d5a1610eb35c9a14105d3ab8555a54717406aa",["Text"]="-----------------------------------\n-- Slice\n-- Scythe weapon skill\n-- Skill level: 5\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Modifiers: STR:100%\n-- 100%TP     200%TP     300%TP\n-- 1.50     1.75    2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.5, 1.75, 2.0 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/slug_shot.lua"]={["Path"]="scripts/actions/weaponskills/slug_shot.lua",["SHA256"]="fdfbfc035a7324eb8c04a8ce3c722e1c7b7fb4d58bf6b2f8f4a17151e3ccd324",["Text"]="-----------------------------------\n-- Slug Shot\n-- Marksmanship weapon skill\n-- Skill Level: 175\n-- Delivers an inparams.accurate attack that deals quintuple damage. params.accuracy varies with TP.\n-- Despite the lack of a STR weaponskill mod, STR is still the most potent stat for increasing this weaponskill's damage to the point at which fSTR2 is capped.\n-- Aligned with the Aqua Gorget, Light Gorget & Breeze Gorget.\n-- Aligned with the Aqua Belt, Light Belt & Breeze Belt.\n-- Element: None\n-- Modifiers: AGI:70%\n-- 100%TP    200%TP    300%TP\n-- 5.00      5.00      5.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 5.0, 5.0, 5.0 }\n    params.agi_wsc = 0.3\n    params.accVaries = { -50, 0, 0 } -- TODO: verify 3,000 TP point. Data is unknown.\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.agi_wsc = 0.7\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/smash_axe.lua"]={["Path"]="scripts/actions/weaponskills/smash_axe.lua",["SHA256"]="de0df3a3b9636a7534fa6cc1d1052012f1c29229e439f9be1654889e6535b3ff",["Text"]="-----------------------------------\n-- Smash Axe\n-- Axe weapon skill\n-- Skill level: 40\n-- Stuns enemy. Duration of stun varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Snow Gorget & Aqua Gorget.\n-- Aligned with the Snow Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR:100%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.STUN\n    local actionElement = xi.element.THUNDER\n    local power         = 1\n    local duration      = math.floor(tp / 500 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/sniper_shot.lua"]={["Path"]="scripts/actions/weaponskills/sniper_shot.lua",["SHA256"]="42611575ffdde824e2ade30bbe54e4cdd8623333826713ac4a8a3a8f1d795b94",["Text"]="-----------------------------------\n-- Sniper Shot\n-- Marksmanship weapon skill\n-- Skill Level: 80\n-- Lowers enemy's INT. Chance of params.critical varies with TP.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: AGI:70%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.agi_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.agi_wsc = 0.7\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.INT_DOWN\n    local actionElement = xi.element.FIRE\n    local power         = 10\n    local duration      = math.floor(140 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/sonic_thrust.lua"]={["Path"]="scripts/actions/weaponskills/sonic_thrust.lua",["SHA256"]="22b1b3263f88cf5f27054f2f942c3e8b1791f7cc2732d6c0c6a8bc2336080d02",["Text"]="-----------------------------------\n-- Sonic Thrust\n-- Polearm weapon skill\n-- Skill Level: 300\n-- Delivers an area attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Element: None\n-- Modifiers: STR:40%  DEX:40%\n-- 100%TP    200%TP    300%TP\n-- 3.00       3.7       4.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.25, 3.5 }\n    params.str_wsc = 0.3 params.dex_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.0, 3.7, 4.5 }\n        params.str_wsc = 0.4 params.dex_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/spinning_attack.lua"]={["Path"]="scripts/actions/weaponskills/spinning_attack.lua",["SHA256"]="d3059fea15ec2ac95e3f1de72efee3590b5864ea0af80c0b50a273502c0cddba",["Text"]="-----------------------------------\n-- Spinning Attack\n-- Hand-to-Hand weapon skill\n-- Skill Level: 150\n-- Delivers an area attack. Radius varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Flame Gorget & Thunder Gorget.\n-- Aligned with the Flame Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR: 35%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\n-- TODO: Radius 5y at 2334 TP\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.35\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0 -- http://wiki.ffo.jp/html/2421.html\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/spinning_axe.lua"]={["Path"]="scripts/actions/weaponskills/spinning_axe.lua",["SHA256"]="7781c0e62d5b87e512f9102117769f649673ab1a403ffb0f0469e9a234e47926",["Text"]="-----------------------------------\n-- Spinning Axe\n-- Axe weapon skill\n-- Skill level: 150\n-- Single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Flame Gorget, Soil Gorget & Thunder Gorget.\n-- Aligned with the Flame Belt, Soil Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.50      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.0, 2.5, 3.0 }\n    params.str_wsc = 0.35\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/spinning_scythe.lua"]={["Path"]="scripts/actions/weaponskills/spinning_scythe.lua",["SHA256"]="4365bcc37be08b3aa9a038e8042212063df4d18b2617ace47a62af5548d2ad64",["Text"]="-----------------------------------\n-- Spinning Scythe\n-- Scythe weapon skill\n-- Skill Level: 125\n-- Delivers an area of effect attack. Attack radius varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Aqua Gorget & Soil Gorget.\n-- Aligned with the Aqua Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:60% MND:60%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\n-- TODO: Radius 5y at 2000 TP, 6y at 3000 TP\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6 params.mnd_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/spinning_slash.lua"]={["Path"]="scripts/actions/weaponskills/spinning_slash.lua",["SHA256"]="c5a4bce80fbadf75b06fbc4f2c3a72776db3935817128e2564d1e6574100db13",["Text"]="-----------------------------------\n-- Spinning Slash\n-- Great Sword weapon skill\n-- Skill level: 225\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Modifiers: STR:30%  INT:30%\n-- 100%TP     200%TP     300%TP\n-- 2.5         3        3.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.5, 3.0, 3.5 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.3 params.int_wsc = 0.3\n    params.atkVaries = { 1.5, 1.5, 1.5 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/spiral_hell.lua"]={["Path"]="scripts/actions/weaponskills/spiral_hell.lua",["SHA256"]="77a61bf6f1f8d034e3f4ca016764ae6fea170bdb52e011d0a1e6489e1c8d3737",["Text"]="-----------------------------------\n-- Spiral Hell\n-- Scythe weapon skill\n-- Skill level: 240 QUESTED\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Modifiers: STR:50%  INT:50%\n-- 100%TP     200%TP     300%TP\n-- 1.375     2.75     4.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.375, 1.875, 3.625 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.5 params.int_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.375, 2.75, 4.75 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/spirit_taker.lua"]={["Path"]="scripts/actions/weaponskills/spirit_taker.lua",["SHA256"]="51d9a36d7ad0f36ef8c870283b5bec5fc9c72669eee6dbd9c5325d8fc0006fa4",["Text"]="-----------------------------------\n-- Spirit Taker\n-- Staff weapon skill\n-- Skill Level: 215\n-- Converts damage dealt to own MP. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Not aligned with any \"elemental gorgets\" or \"elemental belts\" due to it's absence of Skillchain properties.\n-- It is a physical weapon skill, and is affected by the user's params.accuracy and the enemy's evasion. It may miss completely.\n-- Element: None\n-- Modifiers: INT:50%  MND:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.int_wsc = 0.5 params.mnd_wsc = 0.5\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    player:addMP(damage)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/spirits_within.lua"]={["Path"]="scripts/actions/weaponskills/spirits_within.lua",["SHA256"]="41702febafe6546c7da1d0932fff33144087bba6d73111334ea463fd7de7c209",["Text"]="-----------------------------------\n-- Spirits Within\n-- Sword weapon skill\n-- Spirits Within Sword Weapon Skill\n-- TrolandAdded by Troland\n-- Skill Level: 175\n-- Delivers an unavoidable attack. Damage varies with HP and TP.\n-- Not aligned with any \"elemental gorgets\" or \"elemental belts\" due to it's absence of Skillchain properties.\n-- Element: None\n-- Modifiers: HP:\n-- 100%TP    200%TP    300%TP\n-- 12.5%       50%      100%\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod  = { 0.0625, 0.1875, 0.46875 } -- https://www.bg-wiki.com/index.php?title=Spirits_Within&oldid=269806\n\n    local attack =\n    {\n        ['type'] = xi.attackType.BREATH,\n        ['slot'] = xi.slot.MAIN,\n        ['weaponType'] = player:getWeaponSkillType(xi.slot.MAIN),\n        ['damageType'] = xi.damageType.ELEMENTAL\n    }\n\n    local calcParams =\n    {\n        wsID = wsID, -- need 'calcParams.wsID' passed to global\n        criticalHit = false,\n        hitsLanded = 1,\n        tpHitsLanded = 0,\n        extraHitsLanded = 0,\n        shadowsAbsorbed = 0,\n        bonusTP = 0\n    }\n\n    local playerHP = player:getHP()\n    local dmg = 0\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod  = { 0.125, 0.5, 1 } -- https://www.bg-wiki.com/ffxi/Spirits_Within\n    end\n\n    local ftp = xi.weaponskills.fTP(tp, params.ftpMod)\n    dmg = math.floor(playerHP * ftp)\n\n    local damage = dmg\n    damage = math.floor(damage * xi.combat.damage.calculateDamageAdjustment(target, false, false, false, true))\n    damage = math.floor(damage * xi.spells.damage.calculateAbsorption(target, xi.element.NONE, false, false, false, true))\n    damage = math.floor(damage * xi.spells.damage.calculateNullification(target, xi.element.NONE, false, false, false, true))\n    damage = math.floor(target:handleSevereDamage(damage, false))\n\n    if damage > 0 then\n        if player:getOffhandDmg() > 0 then\n            calcParams.tpHitsLanded = 2\n        else\n            calcParams.tpHitsLanded = 1\n        end\n    end\n\n    if player:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE + wsID) > 0 then\n        damage = damage * (100 + player:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE + wsID)) / 100\n    end\n\n    damage = damage * xi.settings.main.WEAPON_SKILL_POWER\n    calcParams.finalDmg = damage\n\n    -- Todo: xi.weaponskills.doBreathWeaponskill() instead of all this.\n    damage = xi.weaponskills.takeWeaponskillDamage(target, player, {}, primary, attack, calcParams, action)\n\n    return calcParams.tpHitsLanded, calcParams.extraHitsLanded, calcParams.criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/split_shot.lua"]={["Path"]="scripts/actions/weaponskills/split_shot.lua",["SHA256"]="69ea714039b8d12c3100fcd82b2c79850a6829e16bffd9dae6022f190f9423dc",["Text"]="-----------------------------------\n-- Split Shot\n-- Marksmanship weapon skill\n-- Skill Level: 40\n-- Ignores enemy's defense. Amount ignored varies with TP.\n-- The amount of defense ignored is 0% @ 100TP, 35% @ 200TP and 50% @ 300TP.\n-- Aligned with the Aqua Gorget & Light Gorget.\n-- Aligned with the Aqua Belt & Light Belt.\n-- Element: None\n-- Modifiers: AGI:70%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 1.0, 1.0, 1.0 }\n    params.agi_wsc             = 0.3\n    params.rangedAccuracyBonus = 30 -- https://www.ffxiah.com/forum/topic/52018/luck-of-the-draw-a-corsairs-guide-new/127/#3726841\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.agi_wsc = 0.7\n    end\n\n    -- Defense ignored is 0%, 35%, 50% as per wiki.bluegartr.com\n    params.ignoredDefense = { 0.0, 0.35, 0.5 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/starburst.lua"]={["Path"]="scripts/actions/weaponskills/starburst.lua",["SHA256"]="39faa4909aff4dded8d761a31fa74eef131e17dec1d6a43457f7166d1ae99399",["Text"]="-----------------------------------\n-- Starburst\n-- Staff weapon skill\n-- Skill Level: 100\n-- Deals light or darkness elemental damage. Damage varies with TP.\n-- Aligned with the Shadow Gorget & Aqua Gorget.\n-- Aligned with the Shadow Belt & Aqua Belt.\n-- Element: Light/Dark (Random)\n-- Modifiers: :    STR:40% MND:40%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.0, 2.5 }\n    params.skill = xi.skill.STAFF\n    params.includemab = true\n    params.dStat = xi.mod.INT\n    -- 50/50 shot of being light or dark\n    params.ele = xi.element.LIGHT\n    if math.randomInt(1, 100) <= 50 then\n        params.ele = xi.element.DARK\n    end\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.mnd_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/stardiver.lua"]={["Path"]="scripts/actions/weaponskills/stardiver.lua",["SHA256"]="21ddad3d9b36d3e8a150046dad8d7d9a182131b1cf94311c705949ecb6b013c1",["Text"]="-----------------------------------\n-- Stardiver\n-- Polearm weapon skill\n-- Skill Level: MERIT\n-- Delivers a fourfold attack. Damage varies with TP.\n-- Will stack with Sneak Attack.     reduces params.crit hit evasion by 5%\n-- Element: None\n-- Modifiers: STR:73~85%\n-- 100%TP    200%TP    300%TP\n-- 0.75         1.25       1.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params       = {}\n    params.numHits     = 4\n    params.ftpMod      = { 0.75, 1.25, 1.75 }\n    params.str_wsc     = player:getMerit(xi.merit.STARDIVER) * 0.17\n    params.multiHitfTP = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.7 + player:getMerit(xi.merit.STARDIVER) * 0.03\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.CRIT_HIT_EVASION_DOWN\n    local actionElement = xi.element.EARTH\n    local power         = 5\n    local duration      = math.floor(60 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/starlight.lua"]={["Path"]="scripts/actions/weaponskills/starlight.lua",["SHA256"]="f6252e6f6dcbcbb93f0c7d2547cca42cfbca3f5da2c2c1d65146256788203ac9",["Text"]="-----------------------------------\n-- Starlight\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local lvl = player:getSkillLevel(11) -- get club skill\n    local damage = (lvl - 10) / 9\n    local damagemod = damage * (tp / 1000)\n    damagemod = damagemod * xi.settings.main.WEAPON_SKILL_POWER\n    return 1, 0, false, damagemod\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/steel_cyclone.lua"]={["Path"]="scripts/actions/weaponskills/steel_cyclone.lua",["SHA256"]="fe7856aedc5e2eeb1f5c3b0c77e8e2a06cfc0ce04c54ed25b7feabce0bb34964",["Text"]="-----------------------------------\n-- Steel Cyclone\n-- Great Axe weapon skill\n-- Skill level: 240\n-- Delivers a single-hit attack. Damage varies with TP.\n-- In order to obtain Steel Cyclone, the quest The Weight of Your Limits must be completed.\n-- Will stack with Sneak Attack.\n-- Aligned with the Breeze Gorget, Aqua Gorget & Snow Gorget.\n-- Aligned with the Breeze Belt, Aqua Belt & Snow Belt.\n-- Element: None\n-- Modifiers: STR:60%  VIT:60%\n-- 100%TP    200%TP    300%TP\n-- 1.50       2.5       4.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.5, 1.75, 3.0 }\n    params.str_wsc = 0.5 params.vit_wsc = 0.5\n    params.atkVaries = { 1.66, 1.66, 1.66 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.5, 2.5, 4.0 }\n        params.str_wsc = 0.6 params.vit_wsc = 0.6\n        params.atkVaries = { 1.5, 1.5, 1.5 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/stringing_pummel.lua"]={["Path"]="scripts/actions/weaponskills/stringing_pummel.lua",["SHA256"]="65a782007f73948e34f5809cf78db65b007649fe2e05168b29555b387e02c3f3",["Text"]="-----------------------------------\n-- Stringing Pummel\n-- Sword weapon skill\n-- Skill Level: N/A\n-- Delivers a sixfold attack. Damage varies with TP.  Kenkonken: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Puppetmaster) quest.\n-- Aligned with the Shadow Gorget, Soil Gorget & Flame Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Flame Belt.\n-- Element: Darkness\n-- Modifiers: STR:32% VIT:32%\n-- 100%TP    200%TP    300%TP\n-- 0.75      0.75      0.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 6\n    params.ftpMod = { 0.75, 0.75, 0.75 }\n    params.str_wsc = 0.32 params.vit_wsc = 0.32\n    params.critVaries = { 0.15, 0.30, 0.45 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.0, 1.0, 1.0 }\n        -- http://wiki.ffo.jp/html/15882.html\n    end\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/sturmwind.lua"]={["Path"]="scripts/actions/weaponskills/sturmwind.lua",["SHA256"]="e1c1bb89781d11771908b095b1dc201ab2f177a1ad9e50b26d510263f0f39d71",["Text"]="-----------------------------------\n-- Sturmwind\n-- Great Axe weapon skill\n-- Skill level: 70\n-- Delivers a two-hit attack. Attack varies with TP.\n-- Will stack with Sneak Attack, but only the first hit.\n-- Aligned with the Soil Gorget & Aqua Gorget.\n-- Aligned with the Soil Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- 1.0       2.0       3.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.3\n    params.atkVaries = { 1.0, 2.0, 3.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/sunburst.lua"]={["Path"]="scripts/actions/weaponskills/sunburst.lua",["SHA256"]="157e319d4cfb0a66df775115aaca7d503e8660570f1161dcb6ddc10911b4cb5e",["Text"]="-----------------------------------\n-- Sunburst\n-- Staff weapon skill\n-- Skill Level: 150\n-- Deals light or darkness elemental damage. Damage varies with TP.\n-- Aligned with the Shadow Gorget & Aqua Gorget.\n-- Aligned with the Shadow Belt & Aqua Belt.\n-- Element: Light/Dark\n-- Modifiers: :    STR:40% MND:40%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.50      4.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.5, 4.0 }\n    params.str_wsc = 0.4\n    params.mnd_wsc = 0.4\n    params.skill = xi.skill.STAFF\n    params.includemab = true\n    params.dStat = xi.mod.INT\n    -- 50/50 shot of being light or dark\n    params.ele = xi.element.LIGHT\n    if math.randomInt(1, 100) <= 50 then\n        params.ele = xi.element.DARK\n    end\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.mnd_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/swift_blade.lua"]={["Path"]="scripts/actions/weaponskills/swift_blade.lua",["SHA256"]="a0907fc3a965bf017a18c8e28b2e02e642e5b178eda54260d297c01aad3d7539",["Text"]="-----------------------------------\n-- Swift Blade\n-- Sword weapon skill\n-- Skill Level: 225\n-- Delivers a three-hit attack. params.accuracy varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget & Soil Gorget.\n-- Aligned with the Shadow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:50%  MND:50%\n-- 100%TP    200%TP    300%TP\n-- 1.50      1.50      1.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.5, 1.5, 1.5 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.3\n    -- Sufficient data for ACC bonus/penalty does not exist; assuming no penalty and 10% increase per 1000 TP\n    -- http://wiki.ffo.jp/html/382.html does not list ACC Bonus\n    -- https://www.bg-wiki.com/ffxi/Swift_Blade does not list ACC Bonus\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.5 params.mnd_wsc = 0.5\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_ageha.lua"]={["Path"]="scripts/actions/weaponskills/tachi_ageha.lua",["SHA256"]="4d3b914c969a829a68d2ad75bc195f871e0ba17346653825c8e71d7e98928bad",["Text"]="-----------------------------------\n-- Tachi Ageha\n-- Great Katana weapon skill\n-- Skill Level: 300\n-- Lowers target's defense. Chance of lowering target's defense varies with TP.\n-- 30% Defense Down\n-- Duration of effect is exactly 3 minutes.\n-- Aligned with the Shadow Gorget, Soil Gorget.\n-- Aligned with the Shadow Belt, Soil Belt.\n-- Element: None\n-- Skillchain Properties: Compression/Scission\n-- Modifiers: CHR:60% STR:40%\n-- 100%TP    200%TP    300%TP\n-- 2.625     2.625      2.625\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 2.8, 2.8, 2.8 }\n    params.chr_wsc = 0.50\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod  = { 2.625, 2.625, 2.625 }\n        params.str_wsc = 0.4\n        params.chr_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.DEFENSE_DOWN\n    local actionElement = xi.element.WIND\n    local power         = 25\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_enpi.lua"]={["Path"]="scripts/actions/weaponskills/tachi_enpi.lua",["SHA256"]="c509e6f7824d4947143231edf0b1553b8f3f9c96b3954737ac45388ea58cdf7f",["Text"]="-----------------------------------\n-- Tachi Enpi\n-- Great Katana weapon skill\n-- Skill Level: 5\n-- Delivers a two-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Light Gorget & Soil Gorget.\n-- Aligned with the Light Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/tachi_fudo.lua"]={["Path"]="scripts/actions/weaponskills/tachi_fudo.lua",["SHA256"]="0b06857fe8e99b06a1cd55a94fb62668167489ed949e2d852b61305cabe51001",["Text"]="-----------------------------------\n-- Tachi: Fudo\n-- Great Katana weapon skill\n-- Skill Level: N/A\n-- Deals double damage. Damage varies with TP. Masamune: Aftermath.\n-- Available only when equipped with Masamune (85), Masamune (90), Masamune (95), Hiradennotachi +1 or Hiradennotachi +2.\n-- Aligned with Light Gorget, Snow Gorget & Aqua Gorget.\n-- Aligned with Light Belt, Snow Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR:80%\n-- 100%TP    200%TP    300%TP\n-- 3.75      5.75        8\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.75, 4.75, 5.75 }\n    params.str_wsc = 0.60\n    params.atkVaries = { 2.0, 2.0, 2.0 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.75, 5.75, 8.0 }\n        params.str_wsc = 0.8\n        params.atkVaries = { 1.0, 1.0, 1.0 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"}};
